 body {
   min-height: 100vh;
   margin: 0;
   color: var(--text);
   font-family:
     Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
     sans-serif;
   line-height: 1.6;
   background:
     radial-gradient(circle at top left, rgba(218, 107, 63, 0.18), transparent 34rem),
     linear-gradient(135deg, #fbf6ee 0%, var(--background) 55%, #efe5d7 100%);
 }

 .page-shell {
   width: min(100% - 2rem, 980px);
   margin: 0 auto;
   padding: 4.5rem 0;
 }

 .hero {
   max-width: 720px;
   margin-bottom: 2rem;
 }

 .eyebrow {
   margin: 0 0 0.65rem;
   color: var(--accent-dark);
   font-size: 0.78rem;
   font-weight: 800;
   letter-spacing: 0.12em;
   text-transform: uppercase;
 }

 h1,
 h2,
 h3,
 p {
   margin-top: 0;
 }

 h1 {
   max-width: 12ch;
   margin-bottom: 1rem;
   font-size: clamp(3rem, 9vw, 5.8rem);
   line-height: 0.92;
   letter-spacing: -0.08em;
 }

 .intro {
   max-width: 62ch;
   margin-bottom: 0;
   color: var(--muted);
   font-size: clamp(1.05rem, 2vw, 1.25rem);
 }

 .faq-card {
   padding: clamp(1.25rem, 3vw, 2rem);
   border: 1px solid var(--border);
   border-radius: 2rem;
   background: rgba(255, 250, 242, 0.82);
   box-shadow: var(--shadow);
   backdrop-filter: blur(18px);
 }

 .section-heading {
   display: grid;
   gap: 0.2rem;
   margin-bottom: 1.25rem;
   padding: 0 0.5rem;
 }

 .section-heading h2 {
   margin: 0;
   font-size: clamp(1.4rem, 3vw, 2rem);
   line-height: 1.15;
   letter-spacing: -0.04em;
 }

 .faq-list {
   display: grid;
   gap: 0.85rem;
 }

 .example {
   overflow: clip;
   border: 1px solid var(--border);
   border-radius: 1.25rem;
   background: var(--surface-strong);
   transition:
     border-color 180ms ease,
     box-shadow 180ms ease,
     transform 180ms ease;
 }

 .example:has(.question[aria-expanded="true"]) {
   border-color: rgba(218, 107, 63, 0.38);
   box-shadow: 0 16px 36px rgba(55, 42, 31, 0.1);
 }

 .example h3 {
   margin: 0;
 }

 .question {
   display: flex;
   width: 100%;
   align-items: center;
   justify-content: space-between;
   gap: 1rem;
   border: 0;
   padding: 1.25rem;
   color: inherit;
   font: inherit;
   font-size: 1.05rem;
   font-weight: 800;
   text-align: left;
   background: transparent;
   cursor: pointer;
 }

 .question:hover {
   color: var(--accent-dark);
 }

 .question:focus-visible {
   outline: 4px solid var(--ring);
   outline-offset: -4px;
 }

 .indicator {
   position: relative;
   flex: 0 0 auto;
   width: 2rem;
   height: 2rem;
   border-radius: 999px;
   background: #f8eadf;
 }

 .indicator::before,
 .indicator::after {
   position: absolute;
   top: 50%;
   left: 50%;
   width: 0.8rem;
   height: 0.12rem;
   border-radius: 999px;
   background: var(--accent-dark);
   content: "";
   transform: translate(-50%, -50%);
   transition: transform 180ms ease;
 }

 .indicator::after {
   transform: translate(-50%, -50%) rotate(90deg);
 }

 .question[aria-expanded="true"] .indicator::after {
   transform: translate(-50%, -50%) rotate(0deg);
 }

 .details {
   padding: 0 1.25rem 1.25rem;
   color: var(--muted);
 }

 .details p {
   max-width: 68ch;
   margin-bottom: 0;
 }

 @media (max-width: 640px) {
   .page-shell {
     width: min(100% - 1rem, 980px);
     padding: 2rem 0;
   }

   .faq-card {
     border-radius: 1.35rem;
   }

   .question {
     padding: 1rem;
   }

   .details {
     padding: 0 1rem 1rem;
   }
 }

